const previewNow=645,minute=t=>Number(t.slice(0,2))*60+Number(t.slice(3)),clock=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0'),duration=m=>((Math.floor(m/60)?Math.floor(m/60)+'h ':'')+(m%60?m%60+'m':'')).trim()||'0m';
let meetings=[{id:'launch-meeting',title:'Launch check-in',home:'Acme',start:'11:00',end:'11:30',noteIds:[]},{id:'harbour-meeting',title:'Client status call',home:'Harbour',start:'14:00',end:'14:30',noteIds:[]},{id:'internal-meeting',title:'Team check-in',home:'Agency time',start:'14:15',end:'15:00',noteIds:[]}];
let timeEditing=null,meetingEditing=null;
const workColor=a=>'var(--'+({'Acme':'acme','Beacon':'beacon','Rowan':'rowan','Agency time':'agency','Juniper':'juniper','Northstar':'northstar','Harbour':'harbour','Cedar':'cedar'}[a]||'acme')+')';
const logged=b=>b.kind==='planned'?Math.max(0,Math.min(minute(b.end),previewNow)-minute(b.start)):minute(b.end)-minute(b.start);
const allocation=()=>allocateSharedTime(blocks.map(b=>({id:b.id,account:b.home,start:minute(b.start),end:minute(b.start)+logged(b)})));
const totalLogged=()=>allocation().total;
const credited=b=>allocation().byBlock.get(b.id)||0;
const creditLabel=b=>{const value=credited(b),hours=Math.floor(value/60),minutes=Number((value-hours*60).toFixed(2));return (hours?hours+'h ':'')+(minutes?minutes+'m':hours?'':'0m')+' credited';};
let layoutWidth=root.clientWidth;
new ResizeObserver(()=>{const width=root.clientWidth;if(width!==layoutWidth){layoutWidth=width;renderDay();}}).observe(root);
function workRow(b){return '<div class="recent-row"><span class="time">'+b.start+'–'+b.end+'</span><button type="button" class="recent-main" data-inspect-time="'+b.id+'"><span class="work-dot" style="--work-color:'+workColor(b.home)+'"></span><span>'+esc(b.home)+'<span class="description '+(!b.description?'missing':'')+'">'+esc(b.description||'Add a description')+'</span></span></button><span class="duration">'+creditLabel(b)+'</span></div>';}
function renderDay(){
 const range=['morning','afternoon','day'].includes(state.range)?state.range:'morning',lo=range==='afternoon'?720:480,hi=range==='morning'?720:1080,span=hi-lo,pct=m=>(m-lo)/span*100;
 q('.chrome [data-action=new]').innerHTML=state.workspace==='timesheets'?icon('plus')+'Add time':icon('plus')+'New note';
 if(state.workspace==='timesheets')q('[data-status]').textContent='';
 q('[data-day-summary]').textContent='10:45 · '+duration(totalLogged())+' recorded';
 qa('[data-range]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.range===range)));
 const ticks=Array.from({length:5},(_,i)=>Math.round(lo+span*i/4)),position=b=>'left:'+pct(Math.max(lo,minute(b.start)))+'%;width:calc('+((Math.min(hi,minute(b.end))-Math.max(lo,minute(b.start)))/span*100)+'% - 5px)',visible=b=>minute(b.end)>lo&&minute(b.start)<hi;
 const workLanes=[],workRows=new Map();for(const b of blocks.filter(visible).sort((a,b)=>minute(a.start)-minute(b.start)||a.id.localeCompare(b.id))){let row=workLanes.findIndex(end=>end<=minute(b.start));if(row<0)row=workLanes.length;workLanes[row]=minute(b.end);workRows.set(b.id,row);}const rowHeight=state.timeDraft?62:80,trackHeight=Math.max(state.timeDraft?80:108,workLanes.length*rowHeight+28);
 let html='<div class="axis">'+ticks.map(t=>'<span style="left:'+pct(t)+'%">'+clock(t)+'</span>').join('')+'</div><div class="lane"><span>Work</span><div class="track work-track" style="--grid-width:25%;height:'+trackHeight+'px">';
 html+=blocks.filter(visible).map(b=>{const minutes=minute(b.end)-minute(b.start),pixels=(root.clientWidth-113)*minutes/span,small=pixels<48,micro=pixels<25,label=small?b.home.slice(0,micro?1:2).toUpperCase():b.home,fill=logged(b)/minutes*100;return '<button type="button" class="timeline-block '+(micro?'micro ':'')+(b.kind==='planned'?'planned':'')+'" data-select-block="'+b.id+'" aria-pressed="'+(state.selectedBlock===b.id)+'" aria-label="'+esc(b.home+' · '+(b.description||'Description missing')+' · '+b.start+'–'+b.end)+'" data-tooltip="'+esc(b.home+' · '+(b.description||'Description missing')+' · '+b.start+'–'+b.end)+'" style="'+position(b)+';top:'+(9+workRows.get(b.id)*rowHeight)+'px;--work-color:'+workColor(b.home)+'">'+(b.kind==='planned'?'<span class="elapsed-fill" style="width:'+fill+'%"></span>':'')+'<span>'+esc(label)+'</span>'+(pixels>103?'<span class="block-description">'+esc(b.description||'Description needed')+'</span>':'')+(!micro?'<span class="block-duration">'+minutes+'m</span>':'')+'</button>';}).join('');
 html+=(previewNow>=lo&&previewNow<=hi?'<div class="now-marker" style="left:'+pct(previewNow)+'%"><span>10:45</span></div>':'')+'</div></div>';
 const meetingLanes=[];for(const m of meetings.filter(visible).sort((a,b)=>a.start.localeCompare(b.start))){let i=meetingLanes.findIndex(l=>minute(l.at(-1).end)<=minute(m.start));if(i<0)i=meetingLanes.length;(meetingLanes[i]??=[]).push(m);}
 if(!meetingLanes.length)meetingLanes.push([]);
 html+=meetingLanes.map((lane,i)=>'<div class="lane"><span>'+(i?'':icon('calendar-days'))+'</span><div class="track meeting-track" aria-label="Meeting reservations">'+lane.map(m=>'<button type="button" class="meeting-block" data-inspect-meeting="'+m.id+'" aria-pressed="'+(state.selectedMeeting===m.id)+'" aria-label="'+esc(m.home+' · '+m.title+' · '+m.start+'–'+m.end)+'" data-tooltip="'+esc(m.home+' · '+m.title+' · '+m.start+'–'+m.end)+'" style="'+position(m)+'">'+esc((root.clientWidth<620?'':m.home+' · ')+m.title)+'</button>').join('')+'</div></div>').join('');
 const scheduled=reminders.filter(r=>!r.done&&r.when.slice(0,10)==='2026-11-20'&&minute(r.when.slice(11))>=lo&&minute(r.when.slice(11))<=hi).sort((a,b)=>a.when.localeCompare(b.when)),groups=[];
 for(const r of scheduled){const g=groups.at(-1),distance=span*40/Math.max(220,root.clientWidth-113);if(g&&minute(r.when.slice(11))-minute(g.at(-1).when.slice(11))<distance)g.push(r);else groups.push([r]);}
 html+='<div class="lane reminder-lane"><span aria-label="Reminders">'+icon('bell')+'</span><div class="track">'+groups.map(g=>'<button type="button" class="reminder-mark" '+(g.length>1?'data-reminder-group="'+g.map(r=>r.id).join(',')+'"':'data-edit-reminder="'+g[0].id+'"')+' aria-label="'+esc(g.map(r=>r.label+' · '+r.when.slice(11)).join('; '))+'" style="left:'+(g.reduce((sum,r)=>sum+pct(minute(r.when.slice(11))),0)/g.length)+'%">'+(g.length>1?g.length:icon('diamond'))+'</button>').join('')+'</div></div>';
 q('[data-day-timeline]').innerHTML=html;
 const selected=blocks.find(b=>b.id===state.selectedBlock),next=meetings.filter(m=>minute(m.end)>previewNow).sort((a,b)=>a.start.localeCompare(b.start))[0],meeting=meetings.find(m=>m.id===state.selectedMeeting)||next;
 if(selected){q('[data-selected-entry]').innerHTML='<div class="context-header"><span class="muted">Selected time · '+selected.start+'–'+selected.end+'</span><button type="button" class="quiet" data-day-action="overview">'+icon('x')+'Back to day</button></div><div class="selected-work"><div class="row"><h3 class="grow">'+esc(selected.home)+'</h3><button type="button" data-edit-time="'+selected.id+'">'+icon('pencil')+'Edit</button></div><span>'+esc(selected.description||'Add a description')+'</span><span class="muted">'+duration(minute(selected.end)-minute(selected.start))+' interval · '+creditLabel(selected)+(credited(selected)<logged(selected)?' · Shared minutes split equally':'')+'</span><div class="row">'+selected.noteIds.map(id=>'<button type="button" data-open="'+id+'">'+icon('file-text')+esc(notes.find(n=>n.id===id)?.title||'Untitled note')+'</button>').join('')+'<button type="button" class="quiet" data-link-block="'+selected.id+'">'+icon('link')+'Link note</button></div></div>';}else if(meeting){const relevant=notes.filter(n=>n.home===meeting.home).sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,2);q('[data-selected-entry]').innerHTML='<div class="context-header"><span class="muted">'+(state.selectedMeeting?'Meeting':minute(meeting.start)<=previewNow?'In progress · until '+meeting.end:'Next meeting · in '+(minute(meeting.start)-previewNow)+'m')+'</span>'+(state.selectedMeeting?'<button type="button" class="quiet" data-day-action="overview">Back to day</button>':'')+'</div><div class="meeting-context"><div class="row"><div><h3>'+esc(meeting.title)+'</h3><span class="muted">'+esc(meeting.home)+' · '+meeting.start+'–'+meeting.end+'</span></div><button type="button" class="primary" data-meeting-notes="'+meeting.id+'">'+icon('square-pen')+(meeting.noteIds.length?'Open notes':'Take notes')+'</button></div><div class="context-notes"><span class="muted">Useful notes</span>'+relevant.map(n=>'<button type="button" data-open="'+n.id+'">'+esc(n.title||'Untitled note')+'</button>').join('')+'<button type="button" data-edit-meeting="'+meeting.id+'" aria-label="Edit meeting">'+icon('pencil')+'</button></div></div>';}else q('[data-selected-entry]').innerHTML='<div class="empty-day"><h3>The rest of your day</h3><button type="button" data-day-action="add-time">Add time</button></div>';
 const recent=blocks.filter(b=>logged(b)>0).sort((a,b)=>b.start.localeCompare(a.start));q('[data-recent-work]').innerHTML=recent.slice(0,3).map(workRow).join('');q('[data-last-entry]').textContent=recent.length?'Last entry '+recent[0].end:'';q('[data-blocks]').innerHTML=[...blocks].sort((a,b)=>a.start.localeCompare(b.start)).map(workRow).join('');q('[data-day-entries]>summary').textContent='All entries · '+blocks.length;
 const due=reminders.filter(r=>!r.done&&r.when<='2026-11-20T10:45').sort((a,b)=>a.when.localeCompare(b.when));if(!due.some(r=>r.id===state.selectedReminder))state.selectedReminder=due[0]?.id||null;
 q('[data-due]').textContent=due.length;
 q('[data-queue]').innerHTML='<h3>Reminders <span class="muted">'+due.length+' due</span></h3>'+due.slice(0,3).map(r=>'<div class="queue-row"><button type="button" data-select-reminder="'+r.id+'" aria-expanded="'+(r.id===state.selectedReminder)+'">'+esc(r.label)+'</button><span class="muted">'+esc(r.home)+' · '+(r.when.slice(0,10)!=='2026-11-20'?'Yesterday':r.when.slice(11))+'</span>'+(r.id===state.selectedReminder?'<div class="row"><button type="button" data-edit-reminder="'+r.id+'">Move</button><button type="button" data-done="'+r.id+'">Done</button>'+(r.noteId?'<button type="button" data-open="'+r.noteId+'">Note</button>':'')+'</div>':'')+'</div>').join('')+(due.length>3?'<button type="button" class="queue-more" data-day-action="all-reminders">'+(due.length-3)+' more due '+icon('arrow-right')+'</button>':'');
 q('[data-action=back-list]').classList.toggle('has-history',state.back.length>0);q('[data-action=back-list]').innerHTML=icon('arrow-left')+(state.back.length?'Previous note':'Notes');q('[data-action=undo-move]').hidden=!undoMove;icons();
}
function timeForm(id=null){timeEditing=id;const b=blocks.find(b=>b.id===id),past=blocks.filter(b=>minute(b.end)<=previewNow).sort((a,b)=>b.end.localeCompare(a.end)),start=b?.start||past[0]?.end||'10:15';openDialog('time-entry',b?'Edit time':'Add time','<div class="fields"><label>Account<select data-time-home><option value="">Choose an account</option>'+accounts.map(a=>'<option '+(a===b?.home?'selected':'')+'>'+a+'</option>').join('')+'</select></label><div class="time-form-grid"><label>From<input type="time" data-time-start value="'+start+'"></label><label>Until<input type="time" data-time-end value="'+(b?.end||clock(Math.max(previewNow,minute(start)+15)))+'"></label></div><label>Description<input data-time-description placeholder="Press office, client call…" value="'+esc(b?.description||'')+'"></label></div><p class="error muted" data-time-error hidden></p><div class="actions"><button type="button" data-action="close-dialog">Cancel</button><button type="button" class="primary" data-day-action="save-time">'+(b?'Update':'Add time')+'</button></div>');}
function saveTimeEntry(){const home=q('[data-time-home]').value,start=q('[data-time-start]').value,end=q('[data-time-end]').value,error=q('[data-time-error]');let message='';if(!home||!start||!end||minute(end)<=minute(start))message='Choose an account and a valid interval.';if(message){error.hidden=false;error.textContent=message;return;}const b=blocks.find(b=>b.id===timeEditing),value={home,start,end,description:q('[data-time-description]').value.trim(),kind:minute(end)>previewNow?'planned':'recorded'};if(b)Object.assign(b,value);else blocks.push({id:'work-'+Date.now(),...value,noteIds:[]});closeDialog();state.selectedBlock=null;state.selectedMeeting=null;render();persist();say(b?'Time updated':'Time added');}
function editMeeting(id){meetingEditing=id;const m=meetings.find(m=>m.id===id);openDialog('meeting','Edit meeting','<div class="fields"><label>Meeting<input data-meeting-title value="'+esc(m.title)+'"></label><div class="time-form-grid"><label>From<input type="time" data-meeting-start value="'+m.start+'"></label><label>Until<input type="time" data-meeting-end value="'+m.end+'"></label></div></div><p class="error muted" data-meeting-error hidden>Choose a valid start and end.</p><div class="actions"><button type="button" data-action="close-dialog">Cancel</button><button type="button" class="primary" data-day-action="save-meeting">Update meeting</button></div>');}
function takeMeetingNotes(id){const m=meetings.find(m=>m.id===id);if(m.noteIds.length){openNote(m.noteIds[0],true);return;}newNote(true);current().home=m.home;current().meetingId=m.id;m.noteIds.push(state.selected);meta();persist();editor().focus();say(m.home+' · '+m.title);}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let handled=true;
 if(b.dataset.action==='new'&&state.workspace==='timesheets'||b.dataset.dayAction==='add-time')timeForm();
 else if(b.dataset.editTime)timeForm(b.dataset.editTime);
 else if(b.dataset.inspectTime){state.selectedBlock=b.dataset.inspectTime;state.selectedMeeting=null;renderDay();persist();}
 else if(b.dataset.inspectMeeting){state.selectedMeeting=b.dataset.inspectMeeting;state.selectedBlock=null;renderDay();persist();}
 else if(b.dataset.range){state.range=b.dataset.range;renderDay();persist();}
 else if(b.dataset.meetingNotes)takeMeetingNotes(b.dataset.meetingNotes);
 else if(b.dataset.editMeeting)editMeeting(b.dataset.editMeeting);
 else if(b.dataset.dayAction==='overview'){state.selectedMeeting=null;state.selectedBlock=null;renderDay();persist();}
 else if(b.dataset.dayAction==='save-time')saveTimeEntry();
 else if(b.dataset.dayAction==='save-meeting'){const start=q('[data-meeting-start]').value,end=q('[data-meeting-end]').value;if(!start||!end||minute(end)<=minute(start)){q('[data-meeting-error]').hidden=false;}else{Object.assign(meetings.find(m=>m.id===meetingEditing),{title:q('[data-meeting-title]').value.trim()||'Meeting',start,end});closeDialog();renderDay();persist();}}
 else if(b.dataset.dayAction==='all-reminders')openDialog('due-list','Due reminders',reminders.filter(r=>!r.done&&r.when<='2026-11-20T10:45').sort((a,b)=>a.when.localeCompare(b.when)).map(r=>'<div class="result-row"><button type="button" data-edit-reminder="'+r.id+'"><span>'+esc(r.label)+'</span><span class="muted">'+esc(r.home)+' · '+r.when.replace('T',' ')+'</span></button></div>').join(''));
 else handled=false;
 if(handled){e.preventDefault();e.stopImmediatePropagation();}
},true);
